export function sortCitiesAlphabetically(cities: string[]): string[] {
  return [...cities].sort((a, b) => {
    const cleanA = a.replace(/^(Kab\.\s*|Kota\s*)/i, '').trim();
    const cleanB = b.replace(/^(Kab\.\s*|Kota\s*)/i, '').trim();
    const cmp = cleanA.localeCompare(cleanB, 'id');
    if (cmp !== 0) return cmp;
    return a.localeCompare(b, 'id');
  });
}

